        <q-input v-model="timeFrom" dense outlined clearable type="time" label="Hora desde" class="col-6 col-md-2" @update:model-value="load"><template #prepend><q-icon name="schedule"/></template></q-input><q-input v-model="timeTo" dense outlined clearable type="time" label="Hora hasta" class="col-6 col-md-2" @update:model-value="load"><template #prepend><q-icon name="schedule"/></template></q-input>
        <div v-if="summary.facturas_rechazadas" class="col-12">
