        <template #body-cell-online="p"><q-td :props="p"><q-icon :name="sendStatus(p.row).icon" :color="sendStatus(p.row).color" size="19px"><q-tooltip>{{sendStatus(p.row).label}}</q-tooltip></q-icon></q-td></template>
        <template #body-cell-fecha_facturada="p"><q-td :props="p"><template v-if="p.value"><div :class="p.row.reemitida_en?'text-teal-9 text-weight-medium':''">{{formatDate(p.value)}}</div><div v-if="p.row.reemitida_en" class="text-caption text-grey-7">reemitida por {{p.row.reemitida_por||'—'}}</div><q-tooltip v-if="p.row.reemitida_en">La venta es del {{formatDate(p.row.fecha)}} pero se facturó el {{formatDate(p.value)}}.</q-tooltip></template><span v-else class="text-grey-6">—</span></q-td></template>
