        <template #body-cell-actions="p"><q-td :props="p"><q-btn-dropdown dense flat color="primary" icon="more_vert" dropdown-icon="none"><q-list dense style="min-width:220px"><q-item clickable v-close-popup @click="showDetail(p.row)"><q-item-section avatar><q-icon name="visibility" color="primary"/></q-item-section><q-item-section>Ver detalle</q-item-section></q-item><q-item clickable v-close-popup @click="printRow(p.row)"><q-item-section avatar><q-icon name="print" color="blue-grey"/></q-item-section><q-item-section>Imprimir</q-item-section></q-item><template v-if="p.row.tipo_comprobante==='FACTURA'"><q-separator/><q-item clickable v-close-popup @click="verifyTaxes(p.row)"><q-item-section avatar><q-icon name="verified" color="positive"/></q-item-section><q-item-section>Verificar impuestos</q-item-section></q-item><q-item clickable v-close-popup @click="printTaxes(p.row)"><q-item-section avatar><q-icon name="receipt_long" color="primary"/></q-item-section><q-item-section>Imprimir impuestos</q-item-section></q-item><q-item v-if="packetReady(p.row)" clickable v-close-popup class="text-warning" @click="openEventDialog(p.row)"><q-item-section avatar><q-icon name="outbox"/></q-item-section><q-item-section>Enviar paquete</q-item-section></q-item><q-item v-if="packetReady(p.row)&&can('Corregir Fecha Factura SIAT')" clickable v-close-popup color="deep-orange" @click="openEventDialog(p.row,true)"><q-item-section avatar><q-icon name="edit_calendar" color="deep-orange"/></q-item-section><q-item-section class="text-deep-orange">Cambiar fecha y enviar</q-item-section></q-item><q-item v-if="unissued(p.row)&&can('Cambiar Factura a Recibo')" clickable v-close-popup @click="convertToReceipt(p.row)"><q-item-section avatar><q-icon name="swap_horiz" color="orange-9"/></q-item-section><q-item-section class="text-orange-9">Cambiar a RECIBO</q-item-section></q-item><q-item v-if="reissuable(p.row)&&can('Reemitir Factura')" clickable v-close-popup @click="reissue(p.row)"><q-item-section avatar><q-icon name="restart_alt" color="teal-8"/></q-item-section><q-item-section class="text-teal-8">Emitir como FACTURA</q-item-section></q-item><q-item v-if="rejected(p.row)&&can('Corregir Factura Rechazada')" clickable v-close-popup @click="openFixDialog(p.row)"><q-item-section avatar><q-icon name="gpp_bad" color="red-9"/></q-item-section><q-item-section class="text-red-9">Corregir documento y reenviar</q-item-section></q-item></template><q-item v-if="receiptToInvoice(p.row)&&can('Reemitir Factura')" clickable v-close-popup @click="reissue(p.row)"><q-item-section avatar><q-icon name="restart_alt" color="teal-8"/></q-item-section><q-item-section class="text-teal-8">Cambiar a FACTURA</q-item-section></q-item><q-separator/><q-item v-if="can('Anular Ventas')&&p.row.estado==='COMPLETADA'" clickable v-close-popup class="text-negative" @click="cancel(p.row)"><q-item-section avatar><q-icon name="cancel"/></q-item-section><q-item-section>Anular</q-item-section></q-item></q-list></q-btn-dropdown></q-td></template>
