    <q-dialog v-model="reasonsDialog"><q-card style="width:600px;max-width:96vw"><q-card-section class="row items-center"><div class="text-h6">Motivo de anulación</div><q-space/><q-btn flat round dense icon="close" v-close-popup/></q-card-section><q-separator/><q-list separator><q-item v-for="reason in cancellationReasons" :key="reason.codigo" clickable @click="cancelWithReason(reason)"><q-item-section avatar><q-avatar color="primary" text-color="white" size="30px">{{reason.codigo}}</q-avatar></q-item-section><q-item-section>{{reason.descripcion}}</q-item-section><q-item-section side><q-icon name="chevron_right"/></q-item-section></q-item></q-list></q-card></q-dialog>
    <q-dialog v-model="eventDialog"><q-card style="width:560px;max-width:96vw"><q-form @submit.prevent="processEvent"><q-card-section class="row items-center q-py-sm"><q-avatar color="warning" text-color="white" icon="wifi_off"/><div class="q-ml-sm"><div class="text-subtitle1 text-weight-bold">Evento significativo</div><div class="text-caption text-grey-7">Enviar únicamente la factura {{eventForm.saleNumber}}</div></div><q-space/><q-btn flat round dense icon="close" v-close-popup/></q-card-section><q-separator/><q-card-section class="row q-col-gutter-sm"><q-select v-model="eventForm.reason" :options="eventReasons" option-label="descripcion" outlined dense label="Motivo del evento" class="col-12" :rules="[v=>!!v||'Seleccione un motivo']" @update:model-value="reason=>eventForm.description=reason?.descripcion||''"/><q-input v-model="eventForm.description" outlined dense label="Descripción" class="col-12" :rules="[v=>!!v||'Requerido']"/><template v-if="can('Corregir Fecha Factura SIAT')"><q-toggle v-model="eventForm.correctDate" color="warning" label="Corregir fecha de emisión antes de enviar" class="col-12"/><q-input v-if="eventForm.correctDate" v-model="eventForm.emissionDate" type="datetime-local" step="1" outlined dense label="Nueva fecha de emisión" class="col-12" :rules="[v=>!!v||'Requerido']"><template #prepend><q-icon name="edit_calendar"/></template></q-input></template><q-banner v-if="eventForm.failed" rounded class="col-12 bg-red-1 text-red-10"><q-icon name="cloud_off" class="q-mr-xs"/>Esta factura se intentó enviar en línea y falló. Se volverá a firmar como emisión fuera de línea (cambia el CUF, no el número ni el monto) antes de mandarla en el paquete.</q-banner><q-banner rounded class="col-12 bg-orange-1 text-orange-10"><q-icon name="info" class="q-mr-xs"/>Se enviará sólo esta factura. El rango del evento se calculará automáticamente segundo a segundo.</q-banner></q-card-section><q-separator/><q-card-actions align="right"><q-btn flat label="Cancelar" no-caps v-close-popup/><q-btn type="submit" unelevated color="warning" text-color="white" icon="send" label="Registrar y enviar" no-caps :loading="eventLoading"/></q-card-actions></q-form></q-card></q-dialog>
    <q-dialog v-model="fixDialog"><q-card style="width:560px;max-width:96vw"><q-form @submit.prevent="submitFix"><q-card-section class="row items-center q-py-sm"><q-avatar color="red-9" text-color="white" icon="gpp_bad"/><div class="q-ml-sm"><div class="text-subtitle1 text-weight-bold">Corregir factura rechazada</div><div class="text-caption text-grey-7">{{fixForm.numero}} · Bs {{money(fixForm.total)}}</div></div><q-space/><q-btn flat round dense icon="close" v-close-popup/></q-card-section><q-separator/><q-card-section class="row q-col-gutter-sm"><q-banner rounded class="col-12 bg-red-1 text-red-10"><q-icon name="error_outline" class="q-mr-xs"/>Impuestos rechazó esta factura: <b>{{fixForm.motivo||'sin detalle'}}</b></q-banner><q-select v-model="fixForm.tipo_documento" :options="['CI','NIT']" outlined dense label="Tipo de documento" class="col-4" :rules="[v=>!!v||'Requerido']"/><q-input v-model="fixForm.numero_documento" outlined dense label="Número de documento" class="col-5" :rules="[v=>!!v&&v!=='0'||'Requerido']"/><q-input v-model="fixForm.complemento" outlined dense label="Compl." class="col-3"/><q-input v-model="fixForm.cliente_nombre" outlined dense label="Nombre o razón social" class="col-12" :rules="[v=>!!v||'Requerido']"/><q-input v-model="fixForm.cliente_email" outlined dense type="email" label="Correo (opcional)" class="col-12"/><q-banner rounded class="col-12 bg-blue-1 text-blue-10"><q-icon name="info" class="q-mr-xs"/>Se emitirá de nuevo con el mismo número de factura y la fecha de hoy. El monto y los productos no cambian.</q-banner></q-card-section><q-separator/><q-card-actions align="right"><q-btn flat label="Cancelar" no-caps v-close-popup/><q-btn type="submit" unelevated color="red-9" icon="send" label="Corregir y reenviar" no-caps :loading="fixLoading"/></q-card-actions></q-form></q-card></q-dialog>
