      <q-card-section class="row items-center q-py-sm">
        <q-spinner-gears v-if="bulk.corriendo" color="teal-8" size="40px"/>
        <q-avatar v-else :color="bulk.fallidas?'orange-8':'positive'" text-color="white" :icon="bulk.fallidas?'report_problem':'task_alt'"/>
        <div class="q-ml-sm"><div class="text-subtitle1 text-weight-bold">{{bulk.corriendo?'Emitiendo en Impuestos…':(bulk.fallidas?'Terminado con errores':'Listo')}}</div><div class="text-caption text-grey-7">{{bulk.hechas}} de {{bulk.total}} · {{bulk.emitidas}} emitidas · {{bulk.fallidas}} con error<template v-if="bulk.corregidas"> · {{bulk.corregidas}} con CI corregido</template></div></div>
        <q-space/><q-badge outline :color="bulk.corriendo?'teal-8':'grey-7'" :label="reloj(bulk.segundos)"/>
      </q-card-section><q-separator/>
      <q-card-section class="q-pa-sm">
        <q-linear-progress rounded stripe size="18px" :value="bulk.total?bulk.hechas/bulk.total:0" :color="bulk.fallidas?'orange':'teal'"><div class="absolute-full flex flex-center"><q-badge color="transparent" text-color="white" :label="`${Math.round(bulk.total?bulk.hechas/bulk.total*100:0)}%`"/></div></q-linear-progress>
        <div v-if="bulk.corriendo" class="row items-center text-caption text-grey-8 q-mt-sm"><q-spinner color="teal-8" size="16px" class="q-mr-xs"/>Enviando <b class="q-mx-xs">{{bulk.actual}}</b> · cada factura es una llamada a Impuestos y puede tardar hasta 45 s</div>
        <q-list v-if="bulk.errores.length" dense bordered class="q-mt-sm errores-list"><q-item v-for="(e,i) in bulk.errores" :key="i"><q-item-section><q-item-label class="text-red-9">{{e.numero}}</q-item-label><q-item-label caption>{{e.mensaje}}</q-item-label></q-item-section></q-item></q-list>
        <q-banner v-if="!bulk.corriendo&&!bulk.errores.length&&bulk.total" rounded class="bg-green-1 text-green-10 q-mt-sm"><q-icon name="check_circle" class="q-mr-xs"/>Impuestos aceptó {{bulk.total===1?'la factura':'todas las facturas'}}.</q-banner>
      </q-card-section><q-separator/>
