<script setup>
import {computed,getCurrentInstance,reactive,ref} from 'vue'
import {openSiatInvoice,printSale} from '../../addons/ventaPrint'
// La pantalla arranca filtrada al día de hoy completo.
const hoy=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const HORA_INICIO='00:01',HORA_FIN='23:59'
const {proxy}=getCurrentInstance(),rows=ref([]),loading=ref(false),search=ref(''),from=ref(hoy()),to=ref(hoy()),timeFrom=ref(HORA_INICIO),timeTo=ref(HORA_FIN),user=ref(null),sendFilter=ref(null),dialog=ref(false),selected=reactive({}),reasonsDialog=ref(false),taxSale=ref(null),eventDialog=ref(false),eventLoading=ref(false),eventReasons=ref([]),summary=reactive({efectivo:0,qr:0,total:0,descuento:0,cantidad:0,facturas_sin_emitir:0,facturas_rechazadas:0,facturas_envio_invalido:0,facturas_reemitibles:0,recibos_facturables:0,usuarios:[]})
const fixDialog=ref(false),fixLoading=ref(false),fixForm=reactive({id:null,numero:'',total:0,motivo:'',tipo_documento:'CI',numero_documento:'',complemento:'',cliente_nombre:'',cliente_email:''})
const bulkDialog=ref(false),bulk=reactive({total:0,hechas:0,emitidas:0,fallidas:0,corregidas:0,corriendo:false,detener:false,errores:[],actual:'',segundos:0})
const sendFilterOptions=[{label:'Todos',value:null},{label:'Faltan enviar',value:'pendientes'},{label:'Enviadas',value:'enviadas'},{label:'Sin emitir',value:'sin_emitir'},{label:'Rechazadas',value:'rechazadas'},{label:'Envío no válido',value:'envio_invalido'},{label:'Para reemitir',value:'reemitir'},{label:'Recibos facturables',value:'recibos_facturables'}]
const eventForm=reactive({reason:null,description:'',saleId:null,saleNumber:'',correctDate:false,emissionDate:'',failed:false})
const cancellationReasons=[{codigo:1,descripcion:'FACTURA MAL EMITIDA'},{codigo:2,descripcion:'NOTA DE CRÉDITO-DÉBITO MAL EMITIDA'},{codigo:3,descripcion:'DATOS DE EMISIÓN INCORRECTOS'},{codigo:4,descripcion:'FACTURA O NOTA DE CRÉDITO-DÉBITO DEVUELTA'}]
const pagination=ref({page:1,rowsPerPage:10,rowsNumber:0}),money=v=>Number(v||0).toFixed(2),can=p=>proxy.$store.hasPermission(p)
const cards=computed(()=>[{label:'Total vendido',value:summary.total,money:true,icon:'trending_up',color:'primary'},{label:'Efectivo',value:summary.efectivo,money:true,icon:'payments',color:'green'},{label:'QR',value:summary.qr,money:true,icon:'qr_code_2',color:'blue'},{label:'Ventas',value:summary.cantidad,money:false,icon:'receipt_long',color:'purple'}])
const columns=[{name:'actions',label:'',align:'left'},{name:'numero',label:'Nº venta',field:'numero',align:'left'},{name:'tipo_comprobante',label:'Comprobante',field:'tipo_comprobante',align:'center'},{name:'online',label:'Envío',field:'online',align:'center'},{name:'estado_siat',label:'Validez',field:'estado_siat',align:'center'},{name:'fecha',label:'Fecha',field:r=>formatDate(r.fecha),align:'left'},{name:'fecha_facturada',label:'Fecha facturada',field:'fecha_emision_siat',align:'left'},{name:'cliente',label:'Facturado a',field:'cliente_nombre',align:'left'},{name:'usuario',label:'Usuario',field:'usuario_nombre',align:'left'},{name:'tipo_pago',label:'Pago',field:'tipo_pago',align:'center'},{name:'detalles',label:'Productos',field:'detalles_count',align:'left'},{name:'descuento',label:'Descuento',field:'descuento',format:v=>`Bs ${money(v)}`,align:'right'},{name:'total',label:'Total',field:'total',align:'right'},{name:'estado',label:'Estado',field:'estado',align:'center'}]
const detailColumns=[{name:'codigo',label:'Código',field:'codigo',align:'left'},{name:'nombre',label:'Producto',field:'nombre',align:'left'},{name:'cantidad',label:'Cant.',field:'cantidad',align:'center'},{name:'precio',label:'Precio',field:'precio_venta',format:v=>`Bs ${money(v)}`,align:'right'},{name:'total',label:'Total',field:'total',align:'right'}]
const params=()=>({q:search.value,desde:from.value,hasta:to.value,hora_desde:timeFrom.value,hora_hasta:timeTo.value,user_id:user.value?.id,envio:sendFilter.value}),paymentColor=v=>v==='EFECTIVO'?'green':v==='QR'?'blue':'purple',paymentInitial=v=>v==='EFECTIVO'?'E':v==='QR'?'Q':'C'
// Cantidad sin ceros de relleno: 2, 1.5, 1.655.
const qty=v=>{const n=Number(v||0);return Number.isInteger(n)?String(n):String(parseFloat(n.toFixed(3)))}
// Envío en línea que falló y nadie va a reintentar solo (mismo criterio que el backend).
const FAILED_SEND=['ERROR_ENVIO','ENVIANDO','PENDIENTE_CONFIGURACION']
const failedSend=row=>row.tipo_comprobante==='FACTURA'&&!row.online&&FAILED_SEND.includes(row.estado_siat)&&row.estado==='COMPLETADA'
// Tiene CUF y XML firmados, así que puede salir en un paquete de evento significativo.
// Las fallidas se reconvierten a fuera de línea en el backend antes de mandarse.
const packetReady=row=>row.tipo_comprobante==='FACTURA'&&!row.online&&(row.estado_siat==='PENDIENTE_EVENTO'||failedSend(row))&&row.cuf&&row.xml_path&&row.fecha_emision_siat
// Cobrada como factura pero sin CUF: nunca se emitió en Impuestos.
const unissued=row=>row.tipo_comprobante==='FACTURA'&&!row.cuf&&row.estado==='COMPLETADA'
// Factura entregada al cliente que Impuestos rechazó: hay que corregirla y reenviarla.
const rejected=row=>row.tipo_comprobante==='FACTURA'&&row.estado_siat==='OBSERVADA'&&row.estado==='COMPLETADA'
function toggleUnissued(){sendFilter.value=sendFilter.value==='sin_emitir'?null:'sin_emitir';load()}
function toggleRejected(){sendFilter.value=sendFilter.value==='rechazadas'?null:'rechazadas';load()}
function toggleInvalidSend(){sendFilter.value=sendFilter.value==='envio_invalido'?null:'envio_invalido';load()}
function toggleReissue(){sendFilter.value=sendFilter.value==='reemitir'?null:'reemitir';load()}
function toggleReceipts(){sendFilter.value=sendFilter.value==='recibos_facturables'?null:'recibos_facturables';load()}
// Rechazo del SIN que se arregla solo reemitiendo con CI: el documento no es un NIT del padrón.
const INVALID_NIT='NUMERO DOCUMENTO DE TIPO NIT NO ES VALIDO'
const nitRejected=row=>row.estado_siat==='OBSERVADA'&&row.tipo_documento==='NIT'&&(row.siat_mensaje||'').toUpperCase().includes(INVALID_NIT)
// Factura que Impuestos nunca aceptó: el número sigue libre y se puede emitir de nuevo (mismo criterio que el backend).
const reissuable=row=>row.tipo_comprobante==='FACTURA'&&row.estado==='COMPLETADA'&&!row.online&&(nitRejected(row)||((!row.cuf||FAILED_SEND.includes(row.estado_siat))&&!['VALIDADA','ANULADA','OBSERVADA'].includes(row.estado_siat)))
// Un recibo vuelve a ser factura sólo si conserva el documento y el nombre del cliente.
const receiptToInvoice=row=>row.tipo_comprobante==='RECIBO'&&row.estado==='COMPLETADA'&&!!row.cliente_nombre&&!!row.numero_documento&&row.numero_documento!=='0'
function reissue(row){const aviso=nitRejected(row)?` Impuestos rechazó el NIT ${row.numero_documento}, así que se enviará como CI (el número de documento no cambia).`:''
  proxy.$alert.dialog(row.tipo_comprobante==='RECIBO'?'Cambiar a FACTURA':'Emitir como FACTURA',`Se emitirá la factura ${row.numero} en Impuestos con la fecha de hoy. La venta sigue siendo del ${formatDate(row.fecha)}: sólo se registra aparte la fecha en que se facturó. El número, el monto y los productos no cambian.${aviso}`).onOk(()=>runBulk([row]))}
// tipo null = facturas fallidas; 'recibos' = recibos con documento del cliente.
async function reissueAll(tipo=null){const esRecibo=tipo==='recibos'
  try{const{data}=await proxy.$axios.get('/ventas-reemitibles',{params:{...params(),tipo}});if(!data.total)return proxy.$alert.info(esRecibo?'No hay recibos con documento del cliente en este filtro':'No hay facturas por emitir con este filtro')
    const extra=data.total>data.ventas.length?` (las ${data.ventas.length} más antiguas de ${data.total})`:''
    proxy.$alert.dialog(esRecibo?'Facturar todos los recibos':'Emitir todas como factura',`Se emitirá${esRecibo?'n':' de nuevo'} ${data.ventas.length} ${esRecibo?'recibo(s) como factura':'factura(s)'}${extra} en Impuestos con la fecha de hoy. Las ventas conservan su fecha original; la fecha de facturación se guarda aparte. Sólo se incluyen ventas del mes en curso. ¿Continuar?`).onOk(()=>runBulk(data.ventas))}
  catch(e){proxy.$alert.error(e.response?.data?.message||'No se pudo obtener la lista de ventas por facturar')}}
// Se manda de a una: cada factura es una llamada al SIAT que puede tardar, y así
// la barra avanza factura por factura en vez de saltar cada tanda.
async function runBulk(ventas){Object.assign(bulk,{total:ventas.length,hechas:0,emitidas:0,fallidas:0,corregidas:0,corriendo:true,detener:false,errores:[],actual:'',segundos:0})
