      try{const{data}=await proxy.$axios.post('/ventas-reemitir',{ids:[venta.id]})
        bulk.emitidas+=data.emitidas;bulk.fallidas+=data.fallidas
        bulk.corregidas+=data.resultados.filter(r=>r.documento_corregido&&r.emitida).length
