async function submitFix(){fixLoading.value=true;try{const{data}=await proxy.$axios.put(`/ventas/${fixForm.id}/corregir-factura`,{tipo_documento:fixForm.tipo_documento,numero_documento:fixForm.numero_documento,complemento:fixForm.complemento||null,cliente_nombre:fixForm.cliente_nombre,cliente_email:fixForm.cliente_email||null});if(data.aceptada){fixDialog.value=false;proxy.$alert.success(data.mensaje)}else{proxy.$alert.error(data.mensaje)}load()}catch(e){proxy.$alert.error(e.response?.data?.message||'No se pudo reenviar la factura')}finally{fixLoading.value=false}}
function convertToReceipt(row){proxy.$alert.dialog('Cambiar a RECIBO',`La venta ${row.numero} quedó marcada como factura pero nunca se emitió en Impuestos. ¿Convertirla en recibo? El monto y el stock no cambian.`).onOk(()=>proxy.$axios.put(`/ventas/${row.id}/convertir-recibo`).then(({data})=>{proxy.$alert.success(data.mensaje);load()}).catch(e=>proxy.$alert.error(e.response?.data?.message||'No se pudo cambiar el tipo de comprobante')))}
function sendStatus(row){if(row.tipo_comprobante!=='FACTURA')return{label:'NO APLICA',color:'blue-grey',icon:'remove'};if(row.online)return{label:'ENVIADA',color:'positive',icon:'cloud_done'};if(failedSend(row))return{label:'ENVÍO FALLIDO · reenviar como evento',color:'negative',icon:'cloud_off'};return packetReady(row)?{label:'FALTA ENVIAR',color:'warning',icon:'cloud_upload'}:{label:'NO PREPARADA',color:'negative',icon:'error_outline'}}
function taxStatus(row){
  if(row.tipo_comprobante!=='FACTURA')return{label:'NO APLICA',color:'blue-grey',icon:'remove_circle_outline'}
  const statuses={VALIDADA:{label:'VÁLIDA',color:'positive',icon:'verified'},OBSERVADA:{label:'OBSERVADA',color:'negative',icon:'error'},ANULADA:{label:'ANULADA',color:'dark',icon:'block'},ERROR_ENVIO:{label:'NO LLEGÓ A IMPUESTOS',color:'negative',icon:'cloud_off'},ENVIANDO:{label:'ENVIANDO',color:'info',icon:'sync'},PENDIENTE_EVENTO:{label:'PENDIENTE',color:'warning',icon:'schedule'},PENDIENTE_CONFIGURACION:{label:'PENDIENTE',color:'warning',icon:'settings'}}
