function cancelWithReason(reason){reasonsDialog.value=false;confirmCancellation(taxSale.value,reason)}
function confirmCancellation(row,reason=null){const detail=reason?` Motivo: ${reason.descripcion}.`:'';proxy.$alert.dialog(`¿Anular ${row.tipo_comprobante.toLowerCase()} ${row.numero}?${detail} El stock será restaurado.`).onOk(()=>proxy.$axios.put(`/ventas/${row.id}/anular`,reason?{codigo_motivo:reason.codigo}:{}).then(({data})=>{proxy.$alert.success(data.mensaje||'Venta anulada correctamente');load()}).catch(e=>proxy.$alert.error(e.response?.data?.message||'No se pudo anular')))}
async function openEventDialog(row,correctDate=false){if(!row)return;try{const{data}=await proxy.$axios.get('/siat-eventos-significativos');eventReasons.value=data.motivos;const center=new Date(row.fecha_emision_siat||row.fecha),local=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,19);eventForm.saleId=row.id;eventForm.saleNumber=row.numero;eventForm.failed=failedSend(row);eventForm.correctDate=correctDate&&can('Corregir Fecha Factura SIAT');eventForm.emissionDate=local(center);eventForm.reason=eventReasons.value.find(i=>i.codigo===2)||eventReasons.value[0];eventForm.description=eventForm.reason?.descripcion||'';eventDialog.value=true}catch(e){proxy.$alert.error(e.response?.data?.message||'No se pudo preparar el evento significativo')}}
async function processEvent(){eventLoading.value=true;try{const payload={codigo_motivo:eventForm.reason.codigo,descripcion:eventForm.description,venta_id:eventForm.saleId};if(eventForm.correctDate)payload.fecha_emision=eventForm.emissionDate;const{data}=await proxy.$axios.post('/siat-eventos-significativos',payload);eventDialog.value=false;proxy.$alert.success(`Evento ${data.codigo_evento}: factura enviada correctamente`);load()}catch(e){proxy.$alert.error(e.response?.data?.message||'No se pudo procesar el evento significativo')}finally{eventLoading.value=false}}
async function download(type){try{const response=await proxy.$axios.get(`/ventas-exportar/${type}`,{params:params(),responseType:'blob'});const url=URL.createObjectURL(response.data),a=document.createElement('a');a.href=url;a.download=`ventas.${type==='excel'?'xlsx':'pdf'}`;a.click();URL.revokeObjectURL(url)}catch{proxy.$alert.error('No se pudo exportar el reporte')}}
load()
</script>

